import { Router } from 'express';
import { AddTaskToProjectUseCase } from '../../../application/use-cases/AddTaskToProjectUseCase';
import { AssignTaskUseCase } from '../../../application/use-cases/AssignTaskUseCase';
import { ListProjectTasksUseCase } from '../../../application/use-cases/ListProjectTasksUseCase';
import { MarkTaskDoneUseCase } from '../../../application/use-cases/MarkTaskDoneUseCase';
import { Dependencies } from '../../composition/Dependencies';
import { TaskController } from '../controllers/TaskController';

export function taskRoutes(deps: Dependencies): Router {
  const controller = new TaskController(
    new AddTaskToProjectUseCase(deps.projects, deps.tasks, deps.ids),
    new AssignTaskUseCase(deps.tasks, deps.users),
    new ListProjectTasksUseCase(deps.projects, deps.tasks),
    new MarkTaskDoneUseCase(deps.tasks),
  );

  const router = Router();
  router.post('/projects/:projectId/tasks', controller.add);
  router.get('/projects/:projectId/tasks', controller.list);
  router.put('/tasks/:taskId/assignee', controller.assign);
  router.post('/tasks/:taskId/done', controller.markDone);
  return router;
}

